#!/usr/bin/env python3
"""Ingest activities from the tools API → util/autogenerated/activities.py.

This is a minimal pass-through ingest. The legacy activities.py is the
most complex autogen file in the repo (drop tables, quality outcomes,
multi-skill, location-keyword gates) and full byte-level parity is
deferred to a follow-up CR. This ingest captures the API verbatim so the
data is locally available for the optimizer migration work.

Activities have nullable `rewards` (None = no reward at all, distinct
from []).
"""
from __future__ import annotations
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent.parent))
from util.scrapers.tools_api_client import ToolsAPIClient  # noqa: E402
from util.scrapers.tools_api_dump import dump_endpoint  # noqa: E402


# ── Activity behavior flags (explicit, scraper-owned lists) ─────────────
# These mirror scrape_activities.py's sets. emit_activities (in
# old_shape_emitters) imports them to stamp one_time / single_completion
# onto the legacy ActivityInfo entries. The tools API does not expose these
# semantics directly, so they are curated here by activity display name.

# One-time activities: completed in a single action, so they never benefit
# from Double Action's long-run averaging (the optimizer neutralizes DA so
# the steps metric equals the displayed steps). Source: movement + emergency
# activities (https://wiki.walkscape.app/wiki/Movement_Activities) plus the
# hidden single-completion activity "Repair the bank".
ONE_TIME_ACTIVITIES = {
    # Movement activities
    'Explore bog bottom',
    'Explore underwater cave',
    'Spring bat tracking',
    'Venture into the bog',
    'Venture into the hideout',
    'Venture into the woods',
    # Emergency (anti-soft-lock) movement activities
    'Emergency darkness escape (Swamp)',
    'Emergency desert escape',
    'Emergency swim escape',
    'Emergency swim escape (Swamp)',
    'Run for your life',
    # Hidden single-completion activities
    'Repair the bank',
}

# Single-completion activities: can only ever be performed ONCE per character
# (the game gates them via an `actionCompleted` history requirement, e.g.
# "Repair the bank" -> requirements.singulars.uniques.wraithwaterBankRebuild,
# opposite=true). These emit single_completion=True so the optimizer can drop
# them from recommendations once the player flags completion via a custom stat.
# STRICT SUBSET of ONE_TIME_ACTIVITIES — movement activities are repeatable;
# only the hidden uniques are truly once-ever.
SINGLE_COMPLETION_ACTIVITIES = {
    'Repair the bank',
}


def run(client: ToolsAPIClient, *, use_cache: bool = True) -> int:
    out = (
        Path(__file__).resolve().parent.parent
        / 'autogenerated' / 'activities.py'
    )
    n = dump_endpoint(
        client, 'activities', str(out), 'ACTIVITIES',
        use_cache=use_cache,
        docstring=(
            'Activities — minimal pass-through ingest. Legacy '
            'activities.py remains source of truth for the optimizer '
            'until a follow-up ingest builds the full ActivityInstance '
            'shape (drop tables, quality outcomes, multi-skill).'
        ),
    )
    print(f'  [activities         ] {n:4d} entities → activities.py')
    return n


if __name__ == '__main__':
    raise SystemExit(0 if run(ToolsAPIClient()) else 1)
